DROP TABLE IF EXISTS `formhistory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `formhistory` (
  `formHistoryID` int NOT NULL AUTO_INCREMENT,
  `formID_id` int NOT NULL,
  `historyType_id` varchar(255) NOT NULL,
  `releaseForm_id` int DEFAULT NULL,
  `adjustedForm_id` int DEFAULT NULL,
  `overloadForm_id` int DEFAULT NULL,
  `createdBy_id` int NOT NULL,
  `createdDate` date NOT NULL,
  `reviewedDate` date DEFAULT NULL,
  `reviewedBy_id` int DEFAULT NULL,
  `status_id` varchar(255) NOT NULL,
  `rejectReason` text,
  PRIMARY KEY (`formHistoryID`),
  KEY `formhistory_formID_id` (`formID_id`),
  KEY `formhistory_historyType_id` (`historyType_id`),
  KEY `formhistory_releaseForm_id` (`releaseForm_id`),
  KEY `formhistory_adjustedForm_id` (`adjustedForm_id`),
  KEY `formhistory_overloadForm_id` (`overloadForm_id`),
  KEY `formhistory_createdBy_id` (`createdBy_id`),
  KEY `formhistory_reviewedBy_id` (`reviewedBy_id`),
  KEY `formhistory_status_id` (`status_id`),
  CONSTRAINT `formhistory_ibfk_1` FOREIGN KEY (`formID_id`) REFERENCES `laborstatusform` (`laborStatusFormID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `formhistory_ibfk_2` FOREIGN KEY (`historyType_id`) REFERENCES `historytype` (`historyTypeName`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `formhistory_ibfk_3` FOREIGN KEY (`releaseForm_id`) REFERENCES `laborreleaseform` (`laborReleaseFormID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `formhistory_ibfk_4` FOREIGN KEY (`adjustedForm_id`) REFERENCES `adjustedform` (`adjustedFormID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `formhistory_ibfk_5` FOREIGN KEY (`overloadForm_id`) REFERENCES `overloadform` (`overloadFormID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `formhistory_ibfk_6` FOREIGN KEY (`createdBy_id`) REFERENCES `user` (`userID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `formhistory_ibfk_7` FOREIGN KEY (`reviewedBy_id`) REFERENCES `user` (`userID`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `formhistory_ibfk_8` FOREIGN KEY (`status_id`) REFERENCES `status` (`statusName`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=47564 DEFAULT CHARSET=latin1;
