--
-- Table structure for table `laborstatusform`
--

DROP TABLE IF EXISTS `laborstatusform`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `laborstatusform` (
  `laborStatusFormID` int NOT NULL AUTO_INCREMENT,
  `studentName` varchar(255) DEFAULT NULL,
  `termCode_id` int NOT NULL,
  `studentSupervisee_id` varchar(255) NOT NULL,
  `supervisor_id` varchar(255) NOT NULL,
  `department_id` int NOT NULL,
  `jobType` varchar(255) NOT NULL,
  `WLS` varchar(255) NOT NULL,
  `POSN_TITLE` varchar(255) NOT NULL,
  `POSN_CODE` varchar(255) NOT NULL,
  `contractHours` int DEFAULT NULL,
  `weeklyHours` int DEFAULT NULL,
  `startDate` date DEFAULT NULL,
  `endDate` date DEFAULT NULL,
  `supervisorNotes` text,
  `laborDepartmentNotes` text,
  `studentExpirationDate` date DEFAULT NULL,
  `studentResponseDate` datetime DEFAULT NULL,
  `confirmationToken` varchar(40) DEFAULT NULL,
  `studentConfirmation` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`laborStatusFormID`),
  KEY `laborstatusform_termCode_id` (`termCode_id`),
  KEY `laborstatusform_studentSupervisee_id` (`studentSupervisee_id`),
  KEY `laborstatusform_supervisor_id` (`supervisor_id`),
  KEY `laborstatusform_department_id` (`department_id`),
  CONSTRAINT `laborstatusform_ibfk_1` FOREIGN KEY (`termCode_id`) REFERENCES `term` (`termCode`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `laborstatusform_ibfk_2` FOREIGN KEY (`studentSupervisee_id`) REFERENCES `student` (`ID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `laborstatusform_ibfk_3` FOREIGN KEY (`supervisor_id`) REFERENCES `supervisor` (`ID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `laborstatusform_ibfk_4` FOREIGN KEY (`department_id`) REFERENCES `department` (`departmentID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=46781 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

