  `studentOverloadReason` text,
  `financialAidApproved_id` varchar(255) DEFAULT NULL,
  `financialAidApprover_id` int DEFAULT NULL,
  `financialAidReviewDate` date DEFAULT NULL,
  `SAASApproved_id` varchar(255) DEFAULT NULL,
  `SAASApprover_id` int DEFAULT NULL,
  `SAASReviewDate` date DEFAULT NULL,
  `laborApproved_id` varchar(255) DEFAULT NULL,
  `laborApprover_id` int DEFAULT NULL,
  `laborReviewDate` date DEFAULT NULL,
  `SAASInitials` varchar(255) DEFAULT NULL,
  `financialAidInitials` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`overloadFormID`),
  KEY `overloadform_financialAidApproved_id` (`financialAidApproved_id`),
  KEY `overloadform_financialAidApprover_id` (`financialAidApprover_id`),
  KEY `overloadform_SAASApproved_id` (`SAASApproved_id`),
  KEY `overloadform_SAASApprover_id` (`SAASApprover_id`),
  KEY `overloadform_laborApproved_id` (`laborApproved_id`),
  KEY `overloadform_laborApprover_id` (`laborApprover_id`),
  CONSTRAINT `overloadform_ibfk_1` FOREIGN KEY (`financialAidApproved_id`) REFERENCES `status` (`statusName`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `overloadform_ibfk_2` FOREIGN KEY (`financialAidApprover_id`) REFERENCES `user` (`userID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `overloadform_ibfk_3` FOREIGN KEY (`SAASApproved_id`) REFERENCES `status` (`statusName`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `overloadform_ibfk_4` FOREIGN KEY (`SAASApprover_id`) REFERENCES `user` (`userID`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `overloadform_ibfk_5` FOREIGN KEY (`laborApproved_id`) REFERENCES `status` (`statusName`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `overloadform_ibfk_6` FOREIGN KEY (`laborApprover_id`) REFERENCES `user` (`userID`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=938 DEFAULT CHARSET=latin1;
