CREATE TABLE `studentlaborevaluation` (
  `ID` int NOT NULL AUTO_INCREMENT,
  `formHistoryID_id` int NOT NULL,
  `attendance_score` int NOT NULL,
  `attendance_comment` text NOT NULL,
