  `respect_score` int NOT NULL,
  `respect_comment` text NOT NULL,
  `learning_score` int NOT NULL,
  `learning_comment` text NOT NULL,
  `jobSpecific_score` int NOT NULL,
  `jobSpecific_comment` text NOT NULL,
  `transcript_comment` text,
  `is_midyear_evaluation` tinyint(1) NOT NULL,
  `is_submitted` tinyint(1) NOT NULL,
  `submitted_by` varchar(255) NOT NULL,
  `date_submitted` date DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `studentlaborevaluation_formHistoryID_id` (`formHistoryID_id`),
  CONSTRAINT `studentlaborevaluation_ibfk_1` FOREIGN KEY (`formHistoryID_id`) REFERENCES `formhistory` (`formHistoryID`) ON DELETE CASCADE ON UPDATE RESTRICT
