DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `userID` int NOT NULL AUTO_INCREMENT,
  `student_id` varchar(255) DEFAULT NULL,
  `supervisor_id` varchar(255) DEFAULT NULL,
  `username` varchar(255) NOT NULL,
  `isLaborAdmin` tinyint(1) DEFAULT NULL,
  `isFinancialAidAdmin` tinyint(1) DEFAULT NULL,
  `isSaasAdmin` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`userID`),
  KEY `user_student_id` (`student_id`),
  KEY `user_supervisor_id` (`supervisor_id`),
  CONSTRAINT `user_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `student` (`ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `user_ibfk_2` FOREIGN KEY (`supervisor_id`) REFERENCES `supervisor` (`ID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=2417 DEFAULT CHARSET=latin1;
